// carry the full precision emitted by Python, so readability lints are
// disabled. float_cmp is disabled because several tests intentionally
// compare exact NaN/0.0/1.0 corner-case outputs.
#![allow(
    clippy::unreadable_literal,
    clippy::excessive_precision,
    clippy::float_cmp,
    clippy::doc_markdown
)]

