// ===========================================================================
// Helpers (ports of the Python test utilities)
// ===========================================================================

const NO_ARGS: &[f32] = &[];

/// Convert a generated `[[f32; C]; R]` reference into an `Array2`.
fn to_array2<const C: usize>(rows: &[[f32; C]]) -> Array2<f32> {
    let data: Vec<f32> = rows.iter().flatten().copied().collect();
    Array2::from_shape_vec((rows.len(), C), data).unwrap()
}

/// Compare two matrices elementwise (numpy `assert_array_almost_equal`
/// semantics: NaN == NaN passes).
fn assert_matrix_close(
    test: &Array2<f32>,
    expected: &Array2<f32>,
    metric: &str,
    epsilon: f64,
    max_relative: f64,
) {
    assert_eq!(
        test.shape(),
        expected.shape(),
        "shape mismatch for {metric}"
    );
    for (idx, (t, e)) in test.iter().zip(expected.iter()).enumerate() {
        if t.is_nan() && e.is_nan() {
            continue;
        }
        assert!(
            relative_eq(*t, *e, epsilon, max_relative),
            "Distances don't match for metric {} at [{}, {}]: {} != {}",
            metric,
            idx / expected.shape()[1],
            idx % expected.shape()[1],
            t,
            e
        );
    }
}

fn relative_eq(a: f32, b: f32, epsilon: f64, max_relative: f64) -> bool {
    if a == b {
        return true;
    }
    let abs_diff = (f64::from(a) - f64::from(b)).abs();
    abs_diff <= epsilon || abs_diff <= max_relative * f64::from(a).abs().max(f64::from(b).abs())
}

/// Python: `run_test_metric` — build a full distance matrix by calling the
/// named metric on rows of `data`.
fn run_test_metric(metric: &str, data: &Array2<f32>, args: &[f32]) -> Array2<f32> {
    let f = dist::named_distances(metric).unwrap_or_else(|| panic!("metric {metric} not found"));
    let n = data.nrows();
    let mut m = Array2::<f32>::zeros((n, n));
    for i in 0..n {
        for j in 0..n {
            m[(i, j)] = f(&data.row(i).to_vec(), &data.row(j).to_vec(), args);
        }
    }
    m
}

/// Python: `run_test_metric(with_grad=True)` — distance parts of the
/// gradient-pair functions.
fn run_test_metric_with_grad(metric: &str, data: &Array2<f32>, args: &[f32]) -> Array2<f32> {
    let (_, g) = dist::named_distances_with_gradients(metric)
        .unwrap_or_else(|| panic!("gradient metric {metric} not found"));
    let n = data.nrows();
    let mut m = Array2::<f32>::zeros((n, n));
    for i in 0..n {
        for j in 0..n {
            m[(i, j)] = g(&data.row(i).to_vec(), &data.row(j).to_vec(), args).0;
        }
    }
    m
}

fn spatial_check(metric: &str, expected: &Array2<f32>) {
    let data = to_array2(&SPATIAL_DATA);
    let test_matrix = run_test_metric(metric, &data, NO_ARGS);
    assert_matrix_close(&test_matrix, expected, metric, 1e-6, 1e-5);
}

fn binary_check(metric: &str, expected: &Array2<f32>) {
    let data = to_array2(&BINARY_DATA);
    let test_matrix = run_test_metric(metric, &data, NO_ARGS);
    assert_matrix_close(&test_matrix, expected, metric, 1e-6, 1e-5);
}

