#[test]
fn test_hellinger() {
    // Python: hellinger is computed on np.abs(spatial_data)
    let data = to_array2(&SPATIAL_DATA).mapv(f32::abs);
    let test_matrix = run_test_metric("hellinger", &data, NO_ARGS);
    assert_matrix_close(
        &test_matrix,
        &to_array2(&HELLINGER_REF),
        "hellinger",
        1e-6,
        1e-5,
    );

    // Python: pairwise_special_metric(np.abs(spatial_data[:-2]))
    let abs10 = data.slice(ndarray::s![0..10, ..]);
    let pm =
        dist::pairwise_special_metric(abs10, dist::named_distances("hellinger").unwrap(), NO_ARGS);
    assert_matrix_close(
        &pm,
        &to_array2(&HELLINGER_SPECIAL_REF),
        "hellinger special",
        1e-6,
        1e-5,
    );

    // Ensure ll_dirichlet runs (Python: test ensures pairwise_special_metric
    // with metric="ll_dirichlet" does not fail)
    let pm = dist::pairwise_special_metric(
        abs10,
        dist::named_distances("ll_dirichlet").unwrap(),
        NO_ARGS,
    );
    assert_eq!(pm.shape(), &[10, 10]);
}

