#[test]
fn test_seuclidean() {
    let v: &[f32] = &V_SEUCLIDEAN[0];
    let data = to_array2(&SPATIAL_DATA);
    let n = data.nrows();
    let mut test_matrix = Array2::<f32>::zeros((n, n));
    for i in 0..n {
        for j in 0..n {
            test_matrix[(i, j)] =
                dist::standardised_euclidean(&data.row(i).to_vec(), &data.row(j).to_vec(), v);
        }
    }
    assert_matrix_close(
        &test_matrix,
        &to_array2(&SEUCLIDEAN_REF),
        "seuclidean",
        1e-6,
        1e-5,
    );

    // Also exercise the named dispatch + pairwise_distances path
    let pm = dist::pairwise_distances(
        data.view(),
        data.view(),
        dist::named_distances("seuclidean").unwrap(),
        v,
    );
    assert_matrix_close(
        &pm,
        &to_array2(&SEUCLIDEAN_REF),
        "seuclidean pairwise",
        1e-6,
        1e-5,
    );
}

