// ===========================================================================
// Grad metrics match metrics (Python: test_grad_metrics_match_metrics)
// ===========================================================================

#[test]
fn test_grad_metrics_match_metrics() {
    let data = to_array2(&SPATIAL_DATA);

    // The gradient-registered spatial metrics' distance parts
    for (metric, expected) in [
        ("euclidean", &EUCLIDEAN_GRAD_DIST_REF),
        ("manhattan", &MANHATTAN_GRAD_DIST_REF),
        ("chebyshev", &CHEBYSHEV_GRAD_DIST_REF),
        ("minkowski", &MINKOWSKI_GRAD_DIST_REF),
        ("canberra", &CANBERRA_GRAD_DIST_REF),
        ("braycurtis", &BRAYCURTIS_GRAD_DIST_REF),
        ("cosine", &COSINE_GRAD_DIST_REF),
        ("correlation", &CORRELATION_GRAD_DIST_REF),
    ] {
        let test_matrix = run_test_metric_with_grad(metric, &data, NO_ARGS);
        assert_matrix_close(&test_matrix, &to_array2(expected), metric, 1e-6, 1e-5);
    }

    // SEuclidean
    let v: &[f32] = &V_SEUCLIDEAN[0];
    let test_matrix = run_test_metric_with_grad("seuclidean", &data, v);
    assert_matrix_close(
        &test_matrix,
        &to_array2(&SEUCLIDEAN_GRAD_DIST_REF),
        "seuclidean grad",
        1e-6,
        1e-5,
    );

    // Weighted minkowski
    let mut wargs: Vec<f32> = W_WMINKOWSKI[0].to_vec();
    wargs.push(3.0);
    let test_matrix = run_test_metric_with_grad("wminkowski", &data, &wargs);
    assert_matrix_close(
        &test_matrix,
        &to_array2(&WMINKOWSKI_GRAD_DIST_REF),
        "wminkowski grad",
        1e-6,
        1e-5,
    );

    // Mahalanobis
    let vinv: Vec<f32> = MAHALANOBIS_VINV.iter().flatten().copied().collect();
    let test_matrix = run_test_metric_with_grad("mahalanobis", &data, &vinv);
    assert_matrix_close(
        &test_matrix,
        &to_array2(&MAHALANOBIS_GRAD_DIST_REF),
        "mahalanobis grad",
        1e-6,
        1e-5,
    );

    // Hellinger (Python: hellinger_grad on np.abs(spatial_data))
    let abs_data = data.mapv(f32::abs);
    let (_, hell_grad) = dist::named_distances_with_gradients("hellinger").unwrap();
    let n = 10;
    let mut test_matrix = Array2::<f32>::zeros((n, n));
    for i in 0..n {
        for j in 0..n {
            test_matrix[(i, j)] = hell_grad(
                &abs_data.row(i).to_vec(),
                &abs_data.row(j).to_vec(),
                NO_ARGS,
            )
            .0;
        }
    }
    assert_matrix_close(
        &test_matrix,
        &to_array2(&HELLINGER_GRAD_SPECIAL_REF),
        "hellinger grad",
        1e-6,
        1e-5,
    );
}

