#[test]
fn test_pairwise_distances_matches_direct_loops() {
    let data = to_array2(&SPATIAL_DATA);
    let f = dist::named_distances("euclidean").unwrap();
    let pm = dist::pairwise_distances(data.view(), data.view(), f, NO_ARGS);
    let direct = run_test_metric("euclidean", &data, NO_ARGS);
    // Same f32 calls, so results must agree to the last bit
    assert_matrix_close(&pm, &direct, "pairwise vs direct", 1e-7, 1e-7);

    // Rectangular X != Y
    let x = data.slice(ndarray::s![0..4, ..]);
    let y = data.slice(ndarray::s![4..9, ..]);
    let pm = dist::pairwise_distances(x, y, f, NO_ARGS);
    assert_eq!(pm.shape(), &[4, 5]);
    for i in 0..4 {
        for j in 0..5 {
            let d = f(&x.row(i).to_vec(), &y.row(j).to_vec(), NO_ARGS);
            assert_relative_eq!(pm[(i, j)], d, epsilon = 1e-7, max_relative = 1e-7);
        }
    }
}

// ===========================================================================
// Gradient finite-difference checks (Python: test_umap_grads.py)
// ===========================================================================

/// Python: `numerical_grad_x` — finite-difference gradient of
/// metric(x, y) with respect to x.
///
/// eps is 1e-3 (Python uses 1e-6) because the metrics compute in f32:
/// with eps near the f32 rounding noise the central differences are
/// dominated by cancellation.
fn numerical_grad_x(
    metric: dist::MetricFn,
    x: &[f32],
    y: &[f32],
    args: &[f32],
    eps: f32,
    forward_only: bool,
) -> Vec<f32> {
    let mut grad = vec![0.0f32; x.len()];
    let fx = if forward_only {
        metric(x, y, args)
    } else {
        0.0
    };
    for i in 0..x.len() {
        let mut x_fwd = x.to_vec();
        x_fwd[i] += eps;
        if forward_only {
            grad[i] = (metric(&x_fwd, y, args) - fx) / eps;
        } else {
            let mut x_bwd = x.to_vec();
            x_bwd[i] -= eps;
            grad[i] = (metric(&x_fwd, y, args) - metric(&x_bwd, y, args)) / (2.0 * eps);
        }
    }
    grad
}

/// Python: `assert_gradient_matches_finite_diff` — compares the analytic
/// gradient against finite differences and the grad-pair distance against
/// the plain metric.
fn assert_gradient_matches_finite_diff(
    metric: dist::MetricFn,
    grad: dist::GradFn,
    x_rows: &Array2<f32>,
    y_rows: &Array2<f32>,
    args: &[f32],
    forward_only: bool,
    skip_close_coords: bool,
    max_tol: f64,
    mean_tol: f64,
) {
    let eps = 1e-3f32;
    let close_thresh = if skip_close_coords { 1e-2f32 } else { 0.0 };
    let mut errors: Vec<f64> = Vec::new();

    for i in 0..x_rows.nrows() {
        let x = &x_rows.row(i).to_vec();
        let y = &y_rows.row(i).to_vec();

        let mut numeric = numerical_grad_x(metric, x, y, args, eps, forward_only);
        let (_, analytic) = grad(x, y, args);

        if skip_close_coords {
            // Skip coords near zero for distances like Hellinger
            for k in 0..numeric.len() {
                if x[k].abs() < close_thresh || y[k].abs() < close_thresh {
                    numeric[k] = 0.0;
                }
            }
        }

        for k in 0..numeric.len() {
            if x[k].abs() < close_thresh || y[k].abs() < close_thresh {
                continue;
            }
            errors.push((f64::from(numeric[k]) - f64::from(analytic[k])).abs());
        }

        // Check grad dists match with non-grad dists
        let true_dist = metric(x, y, args);
        let analytic_dist = grad(x, y, args).0;
        assert!(
            relative_eq(true_dist, analytic_dist, 1e-6, 1e-6),
            "distance mismatch between metric and grad function: {true_dist} != {analytic_dist}"
        );
    }

    let max_err = errors.iter().copied().fold(0.0f64, f64::max);
    let mean_err = errors.iter().sum::<f64>() / errors.len() as f64;
    assert!(max_err < max_tol, "max tol exceeded: {max_err}");
    assert!(mean_err < mean_tol, "mean tol exceeded: {mean_err}");
}

fn normal_pairs(dim: usize) -> (Array2<f32>, Array2<f32>) {
    (
        to_array2(&NORMAL_PAIRS_X)
            .slice(ndarray::s![0..16, 0..dim])
            .to_owned(),
        to_array2(&NORMAL_PAIRS_Y)
            .slice(ndarray::s![0..16, 0..dim])
            .to_owned(),
    )
}

#[test]
fn test_euclidean_gradient() {
    let (metric, grad) = dist::named_distances_with_gradients("euclidean").unwrap();
    for dim in [4usize, 16] {
        let (x, y) = normal_pairs(dim);
        assert_gradient_matches_finite_diff(
            metric, grad, &x, &y, NO_ARGS, false, false, 2e-2, 2e-3,
        );
    }
}

#[test]
fn test_minkowski_gradient() {
    let (metric, grad) = dist::named_distances_with_gradients("minkowski").unwrap();
    for dim in [4usize, 16] {
        for p in [1.0f32, 2.0, 3.0, 4.0] {
            let (x, y) = normal_pairs(dim);
            assert_gradient_matches_finite_diff(
                metric,
                grad,
                &x,
                &y,
                &[p],
                p == 1.0,
                false,
                2e-2,
                2e-3,
            );
        }
    }
}

