#[test]
fn test_mahalanobis_gradient() {
    let (metric, grad) = dist::named_distances_with_gradients("mahalanobis").unwrap();
    for dim in [4usize, 16] {
        let (x, y) = normal_pairs(dim);
        // diagonal inverse covariance (Python: vinv = np.diag(diag))
        let diag = &DIAG_MAHALANOBIS[0][..dim];
        let mut vinv = vec![0.0f32; dim * dim];
        for (k, &d) in diag.iter().enumerate() {
            vinv[k * dim + k] = d;
        }
        assert_gradient_matches_finite_diff(metric, grad, &x, &y, &vinv, false, false, 2e-2, 2e-3);
    }
}

